defmodule Orchestra.Rollout.Trace do
  use GenServer

  def start_link(_), do: GenServer.start_link(__MODULE__, [], name: __MODULE__)
  def reset, do: GenServer.call(__MODULE__, :reset)
  def record(event, label), do: GenServer.cast(__MODULE__, {:record, event, label})
  def entries, do: GenServer.call(__MODULE__, :entries)

  @impl true
  def init(_), do: {:ok, []}
  @impl true
  def handle_call(:reset, _from, _), do: {:reply, :ok, []}
  @impl true
  def handle_call(:entries, _from, entries), do: {:reply, entries, entries}
  @impl true
  def handle_cast({:record, event, label}, entries), do: {:noreply, entries ++ [{event, label}]}
end

defmodule Orchestra.Rollout.Middleware do
  @behaviour Reactor.Middleware

  @impl true
  def init(_), do: :ok

  @impl true
  def handle_event(event, context, step) do
    label = inspect(step.name)
    Orchestra.Rollout.Trace.record(event, label)
    {:cont, context}
  end

  @impl true
  def terminate(_, _), do: :ok
end

defmodule Orchestra.Rollout.Middleware do
  @behaviour Reactor.Middleware

  @impl true
  def init(context), do: {:ok, context}

  @impl true
  def event(event, context, step) do
    label = inspect(step.name)
    Orchestra.Rollout.Trace.record(event, label)
    {:cont, context}
  end

  @impl true
  def halt(context), do: {:cont, context}
  @impl true
  def error(context, _error), do: {:cont, context}
  @impl true
  def complete(context, _), do: {:cont, context}
  @impl true
  def get_process_context, do: %{}
  @impl true
  def set_process_context(_), do: :ok
end
